// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// Says hello, in any language: "héllo", "你好", "👋".
contract Greeter {
  string public greeting;

  constructor(string memory initial) {
    greeting = initial;
  }

  function setGreeting(string calldata next) external {
    greeting = next;
  }
}
